const cfg = $('Workflow Configuration').first().json;
const runId = $execution.id;
function generateUuidV4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const runUuid = generateUuidV4();
const rows = $input.all().map(i => i.json).slice(0, cfg.maxSourcesPerRun);
return rows.map(r => {
  const src = r.source;
  return { json: {
    source_id: src.id,
    company_name: src.company_name,
    official_careers_url: src.official_careers_url || null,
    official_website_url: src.official_website_url || null,
    existing_ats_provider: src.ats_provider || null,
    existing_automation_eligibility: src.automation_eligibility || null,
    researcher_notes: src.researcher_notes || null,
    selectionReason: r.selection_reason,
    previousIngestionType: r.previous_ingestion_type || null,
    previousConfidence: r.previous_confidence || null,
    previousAnalyzedAt: r.previous_analyzed_at || null,
    runId,
    runUuid,
  } };
});

const cfg = $('Workflow Configuration').first().json;
const results = $input.all().map(i => i.json);
const startedAtMs = new Date(cfg.startedAt).getTime();
const countBy = (key, val) => results.filter(r => r[key] === val).length;

const detectedProviders = {};
for (const r of results) {
  if (r.detected_provider && r.detected_provider !== 'unknown') {
    detectedProviders[r.detected_provider] = (detectedProviders[r.detected_provider] || 0) + 1;
  }
}

const insertsAttempted = results.filter(r => r.insertAttempted === true).length;
const insertsPerformed = results.filter(r => r.insertPerformed === true).length;
const insertFailures = results.filter(r => r.insertAttempted === true && r.insertPerformed !== true).length;
const promotionsAttempted = results.filter(r => r.promotionAttempted === true).length;
const promotionsApplied = results.filter(r => r.promotionApplied === true).length;
const newSources = results.filter(r => r.selectionReason === 'never_analyzed').length;
const retriedSources = results.filter(r => r.selectionReason === 'retry_after_backoff').length;
const retryableNeedsInvestigation = results.filter(r => r.ingestion_type === 'needs_investigation' && r.retryable === true).length;
const structuralNeedsInvestigation = results.filter(r => r.ingestion_type === 'needs_investigation' && r.retryable !== true).length;
const wouldBeAutoPromotedDryRun = results.filter(r => r.wouldBeAutoPromotable === true).length;

return [{ json: {
  mode: cfg.mode,
  environment: cfg.environment,
  runId: results.length ? results[0].runId : $execution.id,
  maxSourcesPerRun: cfg.maxSourcesPerRun,
  sourcesAnalyzed: results.length,
  newSources,
  retriedSources,
  detectedProviders,
  atsAdapterCandidates: countBy('ingestion_type', 'ats_adapter'),
  htmlCandidates: countBy('ingestion_type', 'html'),
  customCandidates: countBy('ingestion_type', 'custom_parser'),
  needsInvestigation: countBy('ingestion_type', 'needs_investigation'),
  retryableNeedsInvestigation,
  structuralNeedsInvestigation,
  stillUnknown: countBy('detected_provider', 'unknown'),
  writeMode: cfg.mode === 'write',
  wouldBeAutoPromotedDryRun,
  insertsAttempted,
  insertsPerformed,
  insertFailures,
  promotionsAttempted,
  promotionsApplied,
  totalDurationMs: Date.now() - startedAtMs,
  results,
  finishedAt: new Date().toISOString(),
} }];

const src = $input.first().json;

function isValidHttpUrl(value) {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim();
  if (!trimmed) return false;
  return /^https?:\/\/[^\s/?#][^\s]*$/i.test(trimmed);
}

const careersValid = isValidHttpUrl(src.official_careers_url);
const websiteValid = isValidHttpUrl(src.official_website_url);

const fetchUrl = careersValid ? src.official_careers_url : (websiteValid ? src.official_website_url : null);
const fetchUrlKind = careersValid ? 'careers' : (websiteValid ? 'website' : null);

return [{ json: { ...src, fetchUrl, fetchUrlKind } }];

const src = $('Choose Fetch Target').first().json;
const resp = $input.first().json;
const networkError = !!resp.error;
const statusCode = resp.statusCode || null;
const bodyText = typeof resp.body === 'string' ? resp.body : (resp.body ? JSON.stringify(resp.body) : '');
const blocked = networkError || !statusCode || statusCode === 401 || statusCode === 403 || statusCode === 429 || statusCode === 999 || statusCode >= 500;
const success = !blocked && statusCode >= 200 && statusCode < 400;

const headers = resp.headers || {};
const serverHeader = typeof headers.server === 'string' ? headers.server.slice(0, 60) : null;
const linkHeader = typeof headers.link === 'string' ? headers.link : '';
const setCookieRaw = headers['set-cookie'];
const setCookieHeader = Array.isArray(setCookieRaw) ? setCookieRaw.join(';') : (typeof setCookieRaw === 'string' ? setCookieRaw : '');

const headerEvidence = {
  server: serverHeader,
  cloudflareDetected: /cloudflare/i.test(serverHeader || '') || /__cf_bm/i.test(setCookieHeader),
  wixDetected: !!headers['x-wix-request-id'],
  wordpressDetected: /wp-json/i.test(linkHeader),
};

const titleMatch = bodyText.match(/<title[^>]*>([^<]{0,200})<\/title>/i);
const pageTitle = titleMatch ? titleMatch[1].trim().slice(0, 200) : null;

const canonicalMatch = bodyText.match(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']{0,300})["']/i);
const canonicalUrl = canonicalMatch ? canonicalMatch[1].slice(0, 300) : null;

return [{ json: {
  ...src,
  httpStatus: statusCode,
  bodyText: success ? bodyText.slice(0, 200000) : '',
  fetchSucceeded: success,
  fetchError: networkError ? String(resp.error) : null,
  headerEvidence,
  pageTitle,
  canonicalUrl,
} }];

const src = $input.first().json;
const url = (src.fetchUrl || '').toLowerCase();
const body = src.bodyText || '';
const haystack = (url + '\n' + body).toLowerCase();

const PROVIDERS = [
  { id: 'greenhouse', signals: ['boards-api.greenhouse.io', 'job-boards.greenhouse.io', 'boards.greenhouse.io'] },
  { id: 'lever', signals: ['api.lever.co', 'jobs.lever.co'] },
  { id: 'workable', signals: ['apply.workable.com'] },
  { id: 'oracle', signals: ['oraclecloud.com', 'hcmui/candidateexperience'] },
  { id: 'sap', signals: ['successfactors.com', 'sapsf.eu'] },
  { id: 'workday', signals: ['myworkdayjobs.com'] },
  { id: 'taleo', signals: ['taleo.net'] },
  { id: 'smartrecruiters', signals: ['jobs.smartrecruiters.com'] },
  { id: 'icims', signals: ['icims.com'] },
];

let match = null;
for (const p of PROVIDERS) {
  for (const sig of p.signals) {
    if (haystack.includes(sig)) { match = { provider: p.id, signal: sig }; break; }
  }
  if (match) break;
}

const OFF_SCOPE_HOSTS = ['linkedin.com'];
const JOB_HUB_KEYWORDS = ['jobs', 'job', 'careers', 'career', 'vacancies', 'vacancy', 'opportunities'];
const JOB_SEARCH_QUERY_HINTS = ['page=', 'q=', 'options=', 'location=', 'search', 'filter', 'category=', 'keyword'];
const JOB_ANCHOR_TEXT_PATTERN = /(job|career|apply|vacanc|recruit|hiring|position|opportunit)/i;

function hostOf(href) {
  const abs = href.match(/^https?:\/\/([^\/?#]+)/i);
  if (abs) return abs[1].toLowerCase().replace(/^www\./, '');
  const proto = href.match(/^\/\/([^\/?#]+)/);
  if (proto) return proto[1].toLowerCase().replace(/^www\./, '');
  return null;
}

const pageHost = hostOf(src.fetchUrl || '') || '';
const rawAnchors = body.match(/<a\s+[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi) || [];
const anchorPattern = /<a\s+[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/i;

const seenHrefs = new Set();
const jobDetailLinks = [];
let jobDetailLinkTotal = 0;
const offScopeHosts = new Set();
const externalDomains = new Set();
let jobSearchExample = null;

for (const raw of rawAnchors.slice(0, 500)) {
  const m = raw.match(anchorPattern);
  if (!m) continue;
  const href = m[1].trim();
  const text = m[2].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
  if (!href || href.startsWith('#') || /^(mailto:|tel:|javascript:)/i.test(href)) continue;
  if (seenHrefs.has(href)) continue;

  const looksJobRelevant = JOB_ANCHOR_TEXT_PATTERN.test(href) || JOB_ANCHOR_TEXT_PATTERN.test(text);
  if (!looksJobRelevant) continue;
  seenHrefs.add(href);

  const host = hostOf(href);
  const isExternal = !!host && host !== pageHost;

  if (isExternal && OFF_SCOPE_HOSTS.some(h => host.includes(h))) {
    offScopeHosts.add(host);
    continue;
  }
  if (isExternal) {
    externalDomains.add(host);
    continue;
  }

  const parts = href.split('?');
  const pathPart = parts[0];
  const queryPart = parts[1];
  const segments = pathPart.split('/').filter(Boolean);
  const lastSegment = (segments[segments.length - 1] || '').toLowerCase();
  const isHubOnlyPath = JOB_HUB_KEYWORDS.includes(lastSegment);
  const hasSearchQuery = !!queryPart && JOB_SEARCH_QUERY_HINTS.some(hint => queryPart.toLowerCase().includes(hint));
  const pathHasHubKeyword = segments.some(seg => JOB_HUB_KEYWORDS.includes(seg.toLowerCase()));
  const parentSegment = segments.length >= 2 ? segments[segments.length - 2].toLowerCase() : '';
  const parentIsHubKeyword = JOB_HUB_KEYWORDS.includes(parentSegment);
  const slugTokens = lastSegment.split(/[-_]+/).filter(Boolean);
  const looksLikeSpecificSlug = slugTokens.length >= 4 || /\d/.test(lastSegment);
  const isPlausibleJobDetail = !isHubOnlyPath && (parentIsHubKeyword || looksLikeSpecificSlug);

  if (isPlausibleJobDetail) {
    jobDetailLinkTotal += 1;
    if (jobDetailLinks.length < 5) jobDetailLinks.push({ href: href.slice(0, 150), text });
  }
  if (pathHasHubKeyword && hasSearchQuery && !jobSearchExample) {
    jobSearchExample = href.slice(0, 200);
  }
}

const ldBlocks = body.match(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
const ldTypeSet = new Set();
for (const block of ldBlocks) {
  const types = block.match(/"@type"\s*:\s*"([^"]+)"/g) || [];
  for (const t of types) {
    const mm = t.match(/"@type"\s*:\s*"([^"]+)"/);
    if (mm && mm[1]) ldTypeSet.add(mm[1].slice(0, 40));
    if (ldTypeSet.size >= 8) break;
  }
  if (ldTypeSet.size >= 8) break;
}
const jsonLdTypes = Array.from(ldTypeSet);
const hasJobPostingSchema = jsonLdTypes.some(t => t.toLowerCase() === 'jobposting') || haystack.includes('schema.org/jobposting');

const pageContext = {
  page_title: src.pageTitle || null,
  canonical_url: src.canonicalUrl || null,
  header_evidence: src.headerEvidence || null,
  json_ld_types: jsonLdTypes,
  distinct_job_detail_links: jobDetailLinks,
  job_detail_link_total: jobDetailLinkTotal,
  job_search_url_example: jobSearchExample,
  off_scope_platforms: Array.from(offScopeHosts).slice(0, 3),
  external_domains_referenced: Array.from(externalDomains).slice(0, 5),
};

let result;
if (match) {
  const directHit = url.includes(match.signal);
  result = {
    detected_provider: match.provider, ingestion_type: 'ats_adapter', confidence: directHit ? 'high' : 'medium', retryable: null,
    evidence: {
      matched_signal: match.signal,
      detection_method: directHit ? 'fetched_url_is_provider_domain' : 'provider_domain_referenced_in_page_content',
      checked_url: src.fetchUrl, http_status: src.httpStatus,
      ...pageContext,
    },
  };
} else {
  const scriptTagCount = (body.match(/<script/gi) || []).length;
  const visibleTextLength = body.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().length;
  const looksLikeSpaShell = scriptTagCount >= 5 && visibleTextLength < 500;
  const hasWeakKeywordSignal = /(job opening|open position|apply now|current openings|career opportunit|view job|job listing)/i.test(body);
  const hasDistinctJobDetailLinks = jobDetailLinks.length >= 1;
  const hasJobSearchStructure = !!jobSearchExample;

  if (looksLikeSpaShell) {
    result = {
      detected_provider: 'unknown', ingestion_type: 'custom_parser', confidence: 'low', retryable: null,
      evidence: { matched_signal: null, detection_method: 'javascript_rendered_shell_detected', checked_url: src.fetchUrl, http_status: src.httpStatus, ...pageContext },
    };
  } else if (hasJobPostingSchema || hasDistinctJobDetailLinks || hasJobSearchStructure) {
    const signal = hasJobPostingSchema ? 'schema.org/JobPosting' : (hasJobSearchStructure ? jobSearchExample : 'distinct_job_detail_links');
    const method = hasJobPostingSchema ? 'jobposting_schema_detected' : (hasJobSearchStructure ? 'job_search_url_structure_detected' : 'distinct_job_detail_links_detected');
    result = {
      detected_provider: 'unknown', ingestion_type: 'html', confidence: 'low', retryable: null,
      evidence: { matched_signal: signal, detection_method: method, checked_url: src.fetchUrl, http_status: src.httpStatus, ...pageContext },
    };
  } else {
    result = {
      detected_provider: 'unknown', ingestion_type: 'needs_investigation', confidence: 'low', retryable: false,
      evidence: {
        matched_signal: null,
        detection_method: offScopeHosts.size > 0 ? 'off_scope_job_destination_only' : 'no_provider_fingerprint_or_job_content_detected',
        checked_url: src.fetchUrl, http_status: src.httpStatus,
        weak_keyword_signal: hasWeakKeywordSignal,
        ...pageContext,
      },
    };
  }
}

return [{ json: {
  source_id: src.source_id, company_name: src.company_name,
  ...result,
  existing_ats_provider: src.existing_ats_provider, existing_automation_eligibility: src.existing_automation_eligibility,
  runId: src.runId,
} }];

const r = $input.first().json;
const wouldBeAutoPromotable = r.ingestion_type === 'ats_adapter' && r.confidence === 'high' && r.detected_provider !== 'unknown';
return [{ json: {
  ...r,
  analyzedAt: new Date().toISOString(),
  wouldBeAutoPromotable,
  insertAttempted: false, insertPerformed: false, insertError: null,
  promotionAttempted: false, promotionApplied: false, promotionReason: null,
} }];

const src = $input.first().json;
const networkError = !!src.fetchError;
const status = src.httpStatus;

const retryable = networkError
  || status === 403
  || status === 429
  || status === 999
  || (typeof status === 'number' && status >= 500);

return [{ json: {
  source_id: src.source_id, company_name: src.company_name,
  detected_provider: 'unknown', ingestion_type: 'needs_investigation', confidence: 'low', retryable,
  evidence: {
    matched_signal: null,
    detection_method: src.fetchError ? 'fetch_network_error' : 'fetch_blocked_or_error_status',
    checked_url: src.fetchUrl, http_status: src.httpStatus,
    page_title: src.pageTitle,
    canonical_url: src.canonicalUrl,
    header_evidence: src.headerEvidence,
  },
  existing_ats_provider: src.existing_ats_provider, existing_automation_eligibility: src.existing_automation_eligibility,
  runId: src.runId,
} }];

const src = $input.first().json;
return [{ json: {
  source_id: src.source_id, company_name: src.company_name,
  detected_provider: 'unknown', ingestion_type: 'needs_investigation', confidence: 'low', retryable: false,
  evidence: { matched_signal: null, detection_method: 'no_public_url_available', checked_url: null, http_status: null },
  existing_ats_provider: src.existing_ats_provider, existing_automation_eligibility: src.existing_automation_eligibility,
  runId: src.runId,
} }];

const src = $('Finalize Classification Result').first().json;
const resp = $input.first().json;
const networkError = !!resp.error;
const statusCode = resp.statusCode || null;
const insertPerformed = !networkError && statusCode >= 200 && statusCode < 300;
const responseBody = resp.body;
const errorMessage = insertPerformed
  ? null
  : (networkError
      ? String(resp.error)
      : (responseBody && typeof responseBody === 'object' && responseBody.message
          ? String(responseBody.message).slice(0, 300)
          : `insert_failed_status_${statusCode}`));

return [{ json: {
  ...src,
  insertAttempted: true,
  insertPerformed,
  insertError: errorMessage,
} }];

const src = $('Evaluate Insert Attempt').first().json;
const resp = $input.first().json;
const networkError = !!resp.error;
const statusCode = resp.statusCode || null;
const httpOk = !networkError && statusCode >= 200 && statusCode < 300;
const body = resp.body;
const row = httpOk && Array.isArray(body) ? body[0] : null;

const promotionApplied = httpOk && !!row && row.promoted === true;
const promotionReason = httpOk
  ? (row ? row.reason : 'promotion_rpc_returned_no_row')
  : (networkError
      ? String(resp.error).slice(0, 300)
      : (body && typeof body === 'object' && body.message ? String(body.message).slice(0, 300) : `promotion_failed_status_${statusCode}`));

return [{ json: {
  ...src,
  promotionAttempted: true,
  promotionApplied,
  promotionReason,
} }];
